mapper.select:
SELECT m.agent_id, r.name, m.memory_count, m.updated_at, JSON_UNQUOTE(JSON_EXTRACT(COALESCE(v.config_json, d.config_json), '$.icon')) AS agent_icon, JSON_UNQUOTE(JSON_EXTRACT(COALESCE(v.config_json, d.config_json), '$.color')) AS agent_color FROM (SELECT agent_id, COUNT(*) AS memory_count, MAX(updated_at) AS updated_at FROM agent_memory WHERE enterprise_id = #{enterprise} AND user_id = #{user} AND expires_at > #{now} GROUP BY agent_id) m JOIN resource r ON r.enterprise_id = #{enterprise} AND r.id = m.agent_id LEFT JOIN resource_version v ON v.enterprise_id = r.enterprise_id AND v.resource_id = r.id AND v.id = r.published_version_id LEFT JOIN resource_draft d ON d.enterprise_id = r.enterprise_id AND d.resource_id = r.id WHERE LOCATE(#{query}, r.name) > 0
AND (m.updated_at < #{after.time} OR (m.updated_at = #{after.time} AND m.agent_id < #{after.id}))
ORDER BY m.updated_at DESC, m.agent_id DESC LIMIT #{limit}
